 1→package perf
 2→
 3→import "context"
 4→
 5→type contextKey struct{}
 6→
 7→// spanFromContext retrieves the current span from context, or nil if none.
 8→func spanFromContext(ctx context.Context) *Span {
 9→	if v := ctx.Value(contextKey{}); v != nil {
10→		if s, ok := v.(*Span); ok {
11→			return s
12→		}
13→	}
14→	return nil
15→}
16→
17→// contextWithSpan returns a new context with the span stored.
18→func contextWithSpan(ctx context.Context, s *Span) context.Context {
19→	return context.WithValue(ctx, contextKey{}, s)
20→}
