  9→// Context keys for logging values.
 10→// Using private types to avoid key collisions.
 11→type contextKey int
 12→
 13→const (
 14→	sessionIDKey contextKey = iota
 15→	parentSessionIDKey
 16→	toolCallIDKey
 17→	componentKey
 18→	agentKey
 19→)
 20→
 21→// WithSession adds a session ID to the context.
 22→// If the context already has a session ID, it becomes the parent session ID.
 23→func WithSession(ctx context.Context, sessionID string) context.Context {
 24→	// If there's an existing session, it becomes the parent
 25→	existing := SessionIDFromContext(ctx)
 26→	if existing != "" && existing != sessionID {
 27→		ctx = context.WithValue(ctx, parentSessionIDKey, existing)
 28→	}
 29→	return context.WithValue(ctx, sessionIDKey, sessionID)
 30→}
 31→
 32→// WithParentSession explicitly sets the parent session ID.
 33→// Use this when you need to set the parent explicitly rather than
 34→// having it inferred from an existing session.
 35→func WithParentSession(ctx context.Context, parentSessionID string) context.Context {
 36→	return context.WithValue(ctx, parentSessionIDKey, parentSessionID)
 37→}
 38→
 39→// WithToolCall adds a tool call ID to the context.
 40→func WithToolCall(ctx context.Context, toolCallID string) context.Context {
 41→	return context.WithValue(ctx, toolCallIDKey, toolCallID)
 42→}
 43→
 44→// WithComponent adds a component name to the context.
 45→// Component names help identify the subsystem generating logs (e.g., "hooks", "strategy", "session").
 46→func WithComponent(ctx context.Context, component string) context.Context {
 47→	return context.WithValue(ctx, componentKey, component)
 48→}
 49→
 50→// WithAgent adds an agent name to the context.
 51→// Agent names identify the AI agent generating activity (e.g., "claude-code", "cursor", "aider").
 52→func WithAgent(ctx context.Context, agentName types.AgentName) context.Context {
 53→	return context.WithValue(ctx, agentKey, string(agentName))
 54→}
 55→
 56→// SessionIDFromContext extracts the session ID from the context.
 57→// Returns empty string if not set.
 58→func SessionIDFromContext(ctx context.Context) string {
 59→	if v := ctx.Value(sessionIDKey); v != nil {
 60→		if s, ok := v.(string); ok {
 61→			return s
 62→		}
 63→	}
 64→	return ""
 65→}
 66→
 67→// ParentSessionIDFromContext extracts the parent session ID from the context.
 68→// Returns empty string if not set.
 69→func ParentSessionIDFromContext(ctx context.Context) string {
 70→	if v := ctx.Value(parentSessionIDKey); v != nil {
 71→		if s, ok := v.(string); ok {
 72→			return s
 73→		}
 74→	}
 75→	return ""
 76→}
 77→
 78→// ToolCallIDFromContext extracts the tool call ID from the context.
 79→// Returns empty string if not set.
 80→func ToolCallIDFromContext(ctx context.Context) string {
 81→	if v := ctx.Value(toolCallIDKey); v != nil {
 82→		if s, ok := v.(string); ok {
 83→			return s
 84→		}
 85→	}
 86→	return ""
 87→}
 88→
 89→// ComponentFromContext extracts the component name from the context.
 90→// Returns empty string if not set.
 91→func ComponentFromContext(ctx context.Context) string {
 92→	if v := ctx.Value(componentKey); v != nil {
 93→		if s, ok := v.(string); ok {
 94→			return s
 95→		}
 96→	}
 97→	return ""
 98→}
 99→
100→// AgentFromContext extracts the agent name from the context.
101→// Returns empty string if not set.
102→func AgentFromContext(ctx context.Context) string {
103→	if v := ctx.Value(agentKey); v != nil {
104→		if s, ok := v.(string); ok {
105→			return s
106→		}
107→	}
108→	return ""
109→}
