 10→func TestStart_CreatesRootSpan(t *testing.T) {
 11→	t.Parallel()
 12→	ctx := context.Background()
 13→
 14→	ctx, span := Start(ctx, "test_op")
 15→	if span == nil {
 16→		t.Fatal("Start() returned nil span")
 17→	}
 18→	if span.name != "test_op" {
 19→		t.Errorf("span.name = %q, want %q", span.name, "test_op")
 20→	}
 21→	if span.parent != nil {
 22→		t.Error("root span should have nil parent")
 23→	}
 24→
 25→	got := spanFromContext(ctx)
 26→	if got != span {
 27→		t.Error("spanFromContext should return the span set by Start")
 28→	}
 29→
 30→	span.End()
 31→}
