 41→		t.Error("child span should reference parent")
 42→	}
 43→	if len(parent.children) != 1 {
 44→		t.Fatalf("parent should have 1 child, got %d", len(parent.children))
 45→	}
 46→	if parent.children[0] != child {
 47→		t.Error("parent.children[0] should be the child span")
 48→	}
 49→
 50→	child.End()
 51→	parent.End()
 52→}
