280→// Helper to initialize a git repo for tests
281→func initGitRepo(t *testing.T, dir string) {
282→	t.Helper()
283→	t.Chdir(dir)
284→	cmd := "git init && git config user.email 'test@test.com' && git config user.name 'Test'"
285→	output, err := execCommand(t, "sh", "-c", cmd)
286→	if err != nil {
287→		t.Fatalf("Failed to init git repo: %v\nOutput: %s", err, output)
288→	}
289→}
