291→func execCommand(t *testing.T, name string, args ...string) (string, error) {
292→	t.Helper()
293→	ctx := context.Background()
294→	cmd := exec.CommandContext(ctx, name, args...)
295→	output, err := cmd.CombinedOutput()
296→	return string(output), err
297→}
