299→func TestLogging_IncludesContextValues(t *testing.T) {
300→	tmpDir := t.TempDir()
301→	t.Chdir(tmpDir)
302→
303→	initGitRepo(t, tmpDir)
304→
305→	sessionID := "2025-01-15-context-test"
306→	err := Init(context.Background(), sessionID)
307→	if err != nil {
308→		t.Fatalf("Init() error = %v", err)
309→	}
310→
311→	// Create context with values
312→	// Note: session_id from context is skipped when Init() has already set a global session ID
313→	ctx := context.Background()
314→	ctx = WithSession(ctx, "context-session-id") // Will be ignored, global takes precedence
315→	ctx = WithToolCall(ctx, "toolu_123")
316→	ctx = WithComponent(ctx, testComponent)
317→	ctx = WithAgent(ctx, testAgent)
318→
319→	// Log with context
320→	Info(ctx, "context test message")
321→
322→	Close()
323→
324→	// Read log file
325→	content, err := os.ReadFile(testLogFilePath(tmpDir))
326→	if err != nil {
327→		t.Fatalf("Failed to read log file: %v", err)
328→	}
329→
330→	// Parse as JSON
331→	var logEntry map[string]interface{}
332→	if err := json.Unmarshal(content, &logEntry); err != nil {
333→		t.Fatalf("Log output is not valid JSON: %v\nContent: %s", err, content)
334→	}
335→
