361→func newTrailUpdateCmd() *cobra.Command {
362→	var statusStr, title, body, branch string
363→	var labelAdd, labelRemove []string
364→
365→	cmd := &cobra.Command{
366→		Use:   "update",
367→		Short: "Update trail metadata",
368→		RunE: func(cmd *cobra.Command, _ []string) error {
369→			return runTrailUpdate(cmd.OutOrStdout(), statusStr, title, body, branch, labelAdd, labelRemove)
370→		},
371→	}
372→
373→	cmd.Flags().StringVar(&statusStr, "status", "", "Update status")
374→	cmd.Flags().StringVar(&title, "title", "", "Update title")
375→	cmd.Flags().StringVar(&body, "body", "", "Update body")
376→	cmd.Flags().StringVar(&branch, "branch", "", "Branch to update trail for (defaults to current)")
377→	cmd.Flags().StringSliceVar(&labelAdd, "add-label", nil, "Add label(s)")
378→	cmd.Flags().StringSliceVar(&labelRemove, "remove-label", nil, "Remove label(s)")
379→
380→	return cmd
