382→
383→func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
384→	repo, err := strategy.OpenRepository(context.Background())
385→	if err != nil {
386→		return fmt.Errorf("failed to open repository: %w", err)
387→	}
388→
389→	// Determine branch
390→	if branch == "" {
391→		branch, err = GetCurrentBranch(context.Background())
392→		if err != nil {
393→			return fmt.Errorf("failed to determine current branch: %w", err)
394→		}
395→	}
396→
397→	store := trail.NewStore(repo)
398→	metadata, err := store.FindByBranch(branch)
399→	if err != nil {
400→		return fmt.Errorf("failed to find trail: %w", err)
401→	}
402→	if metadata == nil {
403→		return fmt.Errorf("no trail found for branch %q", branch)
404→	}
405→
406→	// Interactive mode when no flags are provided
407→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
408→	if noFlags {
409→		// Build status options with current value as default.
410→		// Exclude "merged" and "closed" unless the trail is already in that status
411→		// (otherwise the select would silently reset to the first option).
412→		var statusOptions []huh.Option[string]
413→		for _, s := range trail.ValidStatuses() {
414→			if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
415→				continue
416→			}
417→			label := string(s)
418→			if s == metadata.Status {
419→				label += " (current)"
420→			}
421→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
422→		}
423→		statusStr = string(metadata.Status)
424→		title = metadata.Title
425→		body = metadata.Body
426→
427→		form := NewAccessibleForm(
428→			huh.NewGroup(
429→				huh.NewSelect[string]().
430→					Title("Status").
431→					Options(statusOptions...).
432→					Value(&statusStr),
433→				huh.NewInput().
434→					Title("Title").
435→					Value(&title),
436→				huh.NewText().
437→					Title("Body").
438→					Value(&body),
439→			),
440→		)
441→		if formErr := form.Run(); formErr != nil {
442→			return fmt.Errorf("form cancelled: %w", formErr)
443→		}
444→	}
445→
446→	// Validate status if provided
447→	if statusStr != "" {
448→		status := trail.Status(statusStr)
449→		if !status.IsValid() {
450→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
451→		}
452→	}
453→
454→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
455→		if statusStr != "" {
456→			m.Status = trail.Status(statusStr)
457→		}
458→		if title != "" {
459→			m.Title = title
460→		}
461→		if body != "" {
462→			m.Body = body
463→		}
464→		for _, l := range labelAdd {
465→			if !slices.Contains(m.Labels, l) {
466→				m.Labels = append(m.Labels, l)
467→			}
468→		}
469→		for _, l := range labelRemove {
470→			m.Labels = slices.DeleteFunc(m.Labels, func(v string) bool { return v == l })
471→		}
472→	})
473→	if err != nil {
474→		return fmt.Errorf("failed to update trail: %w", err)
475→	}
476→
477→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
478→	return nil
479→}
480→
481→// defaultBaseBranch is the fallback base branch name when it cannot be determined.
482→const defaultBaseBranch = "main"
483→
484→func formatValidStatuses() string {
485→	statuses := trail.ValidStatuses()
486→	names := make([]string, len(statuses))
487→	for i, s := range statuses {
488→		names[i] = string(s)
489→	}
490→	return strings.Join(names, ", ")
491→}
492→
493→// runTrailCreateInteractive runs the interactive form for trail creation.
494→// Prompts for title, body, branch (derived from title), and status.
495→func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
496→	// Step 1: Title and body
497→	form := NewAccessibleForm(
498→		huh.NewGroup(
499→			huh.NewInput().
500→				Title("Trail title").
501→				Placeholder("What are you working on?").
502→				Value(title),
503→			huh.NewText().
504→				Title("Body (optional)").
505→				Value(body),
506→		),
507→	)
508→	if err := form.Run(); err != nil {
509→		return fmt.Errorf("form cancelled: %w", err)
510→	}
511→	*title = strings.TrimSpace(*title)
512→	if *title == "" {
513→		return errors.New("trail title is required")
514→	}
515→
516→	// Step 2: Branch (derived from title) and status
517→	suggested := slugifyTitle(*title)
518→	*branch = suggested
519→
520→	// Build status options, excluding done/closed
521→	var statusOptions []huh.Option[string]
522→	for _, s := range trail.ValidStatuses() {
523→		if s == trail.StatusMerged || s == trail.StatusClosed {
524→			continue
525→		}
526→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
527→	}
528→	if *statusStr == "" {
529→		*statusStr = string(trail.StatusDraft)
530→	}
531→
532→	form = NewAccessibleForm(
533→		huh.NewGroup(
534→			huh.NewInput().
535→				Title("Branch name").
536→				Placeholder(suggested).
537→				Value(branch),
538→			huh.NewSelect[string]().
539→				Title("Status").
540→				Options(statusOptions...).
541→				Value(statusStr),
542→		),
543→	)
544→	if err := form.Run(); err != nil {
545→		return fmt.Errorf("form cancelled: %w", err)
546→	}
547→	*branch = strings.TrimSpace(*branch)
548→	if *branch == "" {
549→		*branch = suggested
550→	}
551→	return nil
552→}
553→
554→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
555→// Best-effort: silently ignores errors (e.g., no remote, no network).
556→func fetchTrailsBranch() {
557→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
558→	defer cancel()
559→	branchName := paths.TrailsBranchName
560→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
561→
562→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
563→	// Ensure non-interactive fetch in hook/agent contexts
564→	cmd.Stdin = nil
565→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
566→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
567→}
568→
569→// getTrailAuthor returns the GitHub username for the trail author.
570→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
571→func getTrailAuthor(repo *git.Repository) string {
572→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
573→	defer cancel()
574→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
575→	if output, err := cmd.Output(); err == nil {
576→		if login := strings.TrimSpace(string(output)); login != "" {
577→			return login
578→		}
579→	}
580→	name, _ := strategy.GetGitAuthorFromRepo(repo)
581→	return name
582→}
583→
584→// slugifyTitle converts a title string into a branch-friendly slug.
585→// Example: "Add user authentication" -> "add-user-authentication"
586→func slugifyTitle(title string) string {
587→	s := strings.ToLower(strings.TrimSpace(title))
588→	// Replace spaces and underscores with hyphens
589→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
590→	// Remove anything that's not alphanumeric, hyphen, or slash
591→	var b strings.Builder
592→	prevHyphen := false
593→	for _, r := range s {
594→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
595→			b.WriteRune(r)
596→			prevHyphen = false
597→		} else if r == '-' && !prevHyphen {
598→			b.WriteRune('-')
599→			prevHyphen = true
600→		}
601→	}
602→	return strings.Trim(b.String(), "-")
603→}
604→
605→// branchNeedsCreation checks if a branch exists locally.
606→func branchNeedsCreation(repo *git.Repository, branchName string) bool {
607→	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
608→	return err != nil
609→}
610→
611→// createBranch creates a new local branch pointing at HEAD without checking it out.
612→func createBranch(repo *git.Repository, branchName string) error {
613→	head, err := repo.Head()
614→	if err != nil {
615→		return fmt.Errorf("failed to get HEAD: %w", err)
616→	}
617→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
618→	if err := repo.Storer.SetReference(ref); err != nil {
619→		return fmt.Errorf("failed to create branch ref: %w", err)
620→	}
621→	return nil
622→}
623→
624→// pushBranchToOrigin pushes a branch to the origin remote.
625→func pushBranchToOrigin(branchName string) error {
626→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
627→	defer cancel()
628→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
629→	if output, err := cmd.CombinedOutput(); err != nil {
630→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
631→	}
632→	return nil
633→}
