package cli

import (
	"testing"
	"time"
)

func TestParsePerfEntry(t *testing.T) {
	t.Parallel()

	t.Run("valid perf entry", func(t *testing.T) {
		t.Parallel()

		line := `{"time":"2026-01-15T10:30:00.000Z","level":"DEBUG","msg":"perf","component":"perf","op":"post-commit","duration_ms":150,"error":true,"steps.load_session_ms":50,"steps.save_checkpoint_ms":80,"steps.save_checkpoint_err":true}`

		entry := parsePerfEntry(line)
		if entry == nil {
			t.Fatal("parsePerfEntry returned nil for valid perf entry")
		}

		if entry.Op != "post-commit" {
			t.Errorf("Op = %q, want %q", entry.Op, "post-commit")
		}
		if entry.DurationMs != 150 {
			t.Errorf("DurationMs = %d, want %d", entry.DurationMs, 150)
		}
		if !entry.Error {
			t.Error("Error = false, want true")
		}

		expectedTime, _ := time.Parse(time.RFC3339, "2026-01-15T10:30:00.000Z")
		if !entry.Time.Equal(expectedTime) {
			t.Errorf("Time = %v, want %v", entry.Time, expectedTime)
		}

		if len(entry.Steps) != 2 {
			t.Fatalf("len(Steps) = %d, want 2", len(entry.Steps))
		}

		// Steps are sorted alphabetically by name
		if entry.Steps[0].Name != "load_session" {
			t.Errorf("Steps[0].Name = %q, want %q", entry.Steps[0].Name, "load_session")
		}
		if entry.Steps[0].DurationMs != 50 {
			t.Errorf("Steps[0].DurationMs = %d, want %d", entry.Steps[0].DurationMs, 50)
		}
		if entry.Steps[0].Error {
			t.Error("Steps[0].Error = true, want false")
		}

		if entry.Steps[1].Name != "save_checkpoint" {
			t.Errorf("Steps[1].Name = %q, want %q", entry.Steps[1].Name, "save_checkpoint")
		}
		if entry.Steps[1].DurationMs != 80 {
			t.Errorf("Steps[1].DurationMs = %d, want %d", entry.Steps[1].DurationMs, 80)
		}
		if !entry.Steps[1].Error {
			t.Error("Steps[1].Error = false, want true")
		}
	})

	t.Run("non-perf entry returns nil", func(t *testing.T) {
		t.Parallel()

		line := `{"time":"2026-01-15T10:30:00.000Z","level":"INFO","msg":"hook invoked","component":"lifecycle","hook":"post-commit"}`

		entry := parsePerfEntry(line)
		if entry != nil {
			t.Errorf("parsePerfEntry returned %+v for non-perf entry, want nil", entry)
		}
	})

	t.Run("invalid JSON returns nil", func(t *testing.T) {
		t.Parallel()

		entry := parsePerfEntry("this is not json at all{{{")
		if entry != nil {
			t.Errorf("parsePerfEntry returned %+v for invalid JSON, want nil", entry)
		}
	})
}

package cli

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// perfStep represents a single timed step within a perf span.
type perfStep struct {
	Name       string
	DurationMs int64
	Error      bool
}

// perfEntry represents a parsed performance trace log entry.
type perfEntry struct {
	Op         string
	DurationMs int64
	Error      bool
	Time       time.Time
	Steps      []perfStep
}

// parsePerfEntry parses a JSON log line into a perfEntry.
// Returns nil if the line is not valid JSON or is not a perf entry (msg != "perf").
func parsePerfEntry(line string) *perfEntry {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal([]byte(line), &raw); err != nil {
		return nil
	}

	// Check that msg == "perf"
	var msg string
	if msgRaw, ok := raw["msg"]; !ok {
		return nil
	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
		return nil
	}

	entry := &perfEntry{}

	// Extract op
	if opRaw, ok := raw["op"]; ok {
		_ = json.Unmarshal(opRaw, &entry.Op)
	}

	// Extract duration_ms
	if dRaw, ok := raw["duration_ms"]; ok {
		_ = json.Unmarshal(dRaw, &entry.DurationMs)
	}

	// Extract error flag
	if errRaw, ok := raw["error"]; ok {
		_ = json.Unmarshal(errRaw, &entry.Error)
	}

	// Extract time
	if tRaw, ok := raw["time"]; ok {
		var ts string
		if err := json.Unmarshal(tRaw, &ts); err == nil {
			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
				entry.Time = parsed
			}
		}
	}

	// Extract steps by finding keys matching "steps.*_ms"
	stepDurations := make(map[string]int64)
	stepErrors := make(map[string]bool)

	for key, val := range raw {
		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
			name := strings.TrimPrefix(key, "steps.")
			name = strings.TrimSuffix(name, "_ms")

			var ms int64
			if err := json.Unmarshal(val, &ms); err == nil {
				stepDurations[name] = ms
			}
		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
			name := strings.TrimPrefix(key, "steps.")
			name = strings.TrimSuffix(name, "_err")

			var errFlag bool
			if err := json.Unmarshal(val, &errFlag); err == nil {
				stepErrors[name] = errFlag
			}
		}
	}

	// Build steps slice sorted alphabetically by name
	steps := make([]perfStep, 0, len(stepDurations))
	for name, ms := range stepDurations {
		steps = append(steps, perfStep{
			Name:       name,
			DurationMs: ms,
			Error:      stepErrors[name],
		})
	}
	sort.Slice(steps, func(i, j int) bool {
		return steps[i].Name < steps[j].Name
	})

	entry.Steps = steps

	return entry
}

