  1→package cli
  2→
  3→import (
  4→	"bufio"
  5→	"encoding/json"
  6→	"fmt"
  7→	"os"
  8→	"sort"
  9→	"strings"
 10→	"time"
 11→)
 12→
 13→// perfStep represents a single timed step within a perf span.
 14→type perfStep struct {
 15→	Name       string
 16→	DurationMs int64
 17→	Error      bool
 18→}
 19→
 20→// perfEntry represents a parsed performance trace log entry.
 21→type perfEntry struct {
 22→	Op         string
 23→	DurationMs int64
 24→	Error      bool
 25→	Time       time.Time
 26→	Steps      []perfStep
 27→}
 28→
 29→// parsePerfEntry parses a JSON log line into a perfEntry.
 30→// Returns nil if the line is not valid JSON or is not a perf entry (msg != "perf").
 31→func parsePerfEntry(line string) *perfEntry {
 32→	var raw map[string]json.RawMessage
 33→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 34→		return nil
 35→	}
 36→
 37→	// Check that msg == "perf"
 38→	var msg string
 39→	if msgRaw, ok := raw["msg"]; !ok {
 40→		return nil
 41→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 42→		return nil
 43→	}
 44→
 45→	entry := &perfEntry{}
 46→
 47→	// Extract op
 48→	if opRaw, ok := raw["op"]; ok {
 49→		if err := json.Unmarshal(opRaw, &entry.Op); err != nil {
 50→			return nil
 51→		}
 52→	}
 53→
 54→	// Extract duration_ms
 55→	if dRaw, ok := raw["duration_ms"]; ok {
 56→		if err := json.Unmarshal(dRaw, &entry.DurationMs); err != nil {
 57→			return nil
 58→		}
 59→	}
 60→
 61→	// Extract error flag
 62→	if errRaw, ok := raw["error"]; ok {
 63→		if err := json.Unmarshal(errRaw, &entry.Error); err != nil {
 64→			return nil
 65→		}
 66→	}
 67→
 68→	// Extract time
 69→	if tRaw, ok := raw["time"]; ok {
 70→		var ts string
 71→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 72→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 73→				entry.Time = parsed
 74→			}
 75→		}
 76→	}
 77→
 78→	// Extract steps by finding keys matching "steps.*_ms"
 79→	stepDurations := make(map[string]int64)
 80→	stepErrors := make(map[string]bool)
 81→
 82→	for key, val := range raw {
 83→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 84→			name := strings.TrimPrefix(key, "steps.")
 85→			name = strings.TrimSuffix(name, "_ms")
 86→
 87→			var ms int64
 88→			if err := json.Unmarshal(val, &ms); err == nil {
 89→				stepDurations[name] = ms
 90→			}
 91→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 92→			name := strings.TrimPrefix(key, "steps.")
 93→			name = strings.TrimSuffix(name, "_err")
 94→
 95→			var errFlag bool
 96→			if err := json.Unmarshal(val, &errFlag); err == nil {
 97→				stepErrors[name] = errFlag
 98→			}
 99→		}
100→	}
101→
102→	// Build steps slice sorted alphabetically by name
103→	steps := make([]perfStep, 0, len(stepDurations))
104→	for name, ms := range stepDurations {
105→		steps = append(steps, perfStep{
106→			Name:       name,
107→			DurationMs: ms,
108→			Error:      stepErrors[name],
109→		})
110→	}
111→	sort.Slice(steps, func(i, j int) bool {
112→		return steps[i].Name < steps[j].Name
113→	})
114→
115→	entry.Steps = steps
116→
117→	return entry
118→}
119→
120→// collectPerfEntries reads a JSONL log file and returns the last N perf entries,
121→// ordered newest first. If hookFilter is non-empty, only entries with a matching
122→// Op field are included.
123→func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
124→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
125→	if err != nil {
126→		return nil, fmt.Errorf("opening perf log: %w", err)
127→	}
128→	defer f.Close()
129→
130→	var entries []perfEntry
131→
132→	scanner := bufio.NewScanner(f)
133→	for scanner.Scan() {
134→		entry := parsePerfEntry(scanner.Text())
135→		if entry == nil {
136→			continue
137→		}
138→		if hookFilter != "" && entry.Op != hookFilter {
139→			continue
140→		}
141→		entries = append(entries, *entry)
142→	}
143→
144→	if err := scanner.Err(); err != nil {
145→		return nil, fmt.Errorf("reading perf log: %w", err)
146→	}
147→
148→	// Take the last N entries
149→	if len(entries) > last {
150→		entries = entries[len(entries)-last:]
151→	}
152→
153→	// Reverse so newest entries are first
154→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
155→		entries[i], entries[j] = entries[j], entries[i]
156→	}
157→
158→	return entries, nil
159→}
