 12→)
 13→
 14→// perfStep represents a single timed step within a perf span.
 15→type perfStep struct {
 16→	Name       string
 17→	DurationMs int64
 18→	Error      bool
 19→}
 20→
 21→// perfEntry represents a parsed performance trace log entry.
 22→type perfEntry struct {
 23→	Op         string
 24→	DurationMs int64
 25→	Error      bool
 26→	Time       time.Time
 27→	Steps      []perfStep
 28→}
 29→
 30→// parsePerfEntry parses a JSON log line into a perfEntry.
 31→// Returns nil if the line is not valid JSON or is not a perf entry (msg != "perf").
 32→func parsePerfEntry(line string) *perfEntry {
 33→	var raw map[string]json.RawMessage
 34→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 35→		return nil
 36→	}
 37→
 38→	// Check that msg == "perf"
 39→	var msg string
 40→	if msgRaw, ok := raw["msg"]; !ok {
 41→		return nil
 42→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 43→		return nil
 44→	}
 45→
 46→	entry := &perfEntry{}
 47→
 48→	// Extract op
 49→	if opRaw, ok := raw["op"]; ok {
 50→		if err := json.Unmarshal(opRaw, &entry.Op); err != nil {
 51→			return nil
 52→		}
 53→	}
 54→
 55→	// Extract duration_ms
 56→	if dRaw, ok := raw["duration_ms"]; ok {
 57→		if err := json.Unmarshal(dRaw, &entry.DurationMs); err != nil {
 58→			return nil
 59→		}
 60→	}
 61→
 62→	// Extract error flag
 63→	if errRaw, ok := raw["error"]; ok {
 64→		if err := json.Unmarshal(errRaw, &entry.Error); err != nil {
 65→			return nil
 66→		}
 67→	}
 68→
 69→	// Extract time
 70→	if tRaw, ok := raw["time"]; ok {
 71→		var ts string
 72→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 73→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 74→				entry.Time = parsed
 75→			}
 76→		}
 77→	}
 78→
 79→	// Extract steps by finding keys matching "steps.*_ms"
 80→	stepDurations := make(map[string]int64)
 81→	stepErrors := make(map[string]bool)
 82→
 83→	for key, val := range raw {
 84→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 85→			name := strings.TrimPrefix(key, "steps.")
 86→			name = strings.TrimSuffix(name, "_ms")
 87→
 88→			var ms int64
 89→			if err := json.Unmarshal(val, &ms); err == nil {
 90→				stepDurations[name] = ms
 91→			}
 92→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 93→			name := strings.TrimPrefix(key, "steps.")
 94→			name = strings.TrimSuffix(name, "_err")
 95→
 96→			var errFlag bool
 97→			if err := json.Unmarshal(val, &errFlag); err == nil {
 98→				stepErrors[name] = errFlag
 99→			}
100→		}
101→	}
102→
103→	// Build steps slice sorted alphabetically by name
104→	steps := make([]perfStep, 0, len(stepDurations))
105→	for name, ms := range stepDurations {
106→		steps = append(steps, perfStep{
107→			Name:       name,
108→			DurationMs: ms,
109→			Error:      stepErrors[name],
110→		})
111→	}
112→	sort.Slice(steps, func(i, j int) bool {
113→		return steps[i].Name < steps[j].Name
114→	})
115→
116→	entry.Steps = steps
117→
118→	return entry
119→}
120→
121→// collectPerfEntries reads a JSONL log file and returns the last N perf entries,
122→// ordered newest first. If hookFilter is non-empty, only entries with a matching
123→// Op field are included.
124→func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
125→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
126→	if err != nil {
127→		return nil, fmt.Errorf("opening perf log: %w", err)
128→	}
129→	defer f.Close()
130→
131→	var entries []perfEntry
132→
133→	scanner := bufio.NewScanner(f)
134→	for scanner.Scan() {
135→		entry := parsePerfEntry(scanner.Text())
136→		if entry == nil {
137→			continue
138→		}
139→		if hookFilter != "" && entry.Op != hookFilter {
140→			continue
141→		}
142→		entries = append(entries, *entry)
143→	}
144→
145→	if err := scanner.Err(); err != nil {
146→		return nil, fmt.Errorf("reading perf log: %w", err)
147→	}
148→
149→	// Take the last N entries
150→	if len(entries) > last {
151→		entries = entries[len(entries)-last:]
152→	}
153→
154→	// Reverse so newest entries are first
155→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
156→		entries[i], entries[j] = entries[j], entries[i]
157→	}
158→
159→	return entries, nil
160→}
