253→// promptSessionAction asks the user what to do with a stuck session.
254→func promptSessionAction(ss stuckSession) (string, error) {
255→	var action string
256→
257→	options := make([]huh.Option[string], 0, 3)
258→	if ss.HasShadowBranch && ss.CheckpointCount > 0 {
259→		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
260→	}
261→	options = append(options,
262→		huh.NewOption("Discard (remove session data)", "discard"),
263→		huh.NewOption("Skip (leave as-is)", "skip"),
264→	)
265→
266→	form := NewAccessibleForm(
267→		huh.NewGroup(
268→			huh.NewSelect[string]().
269→				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
270→				Options(options...).
271→				Value(&action),
272→		),
273→	)
274→
275→	if err := form.Run(); err != nil {
276→		return "", fmt.Errorf("session fix prompt failed: %w", err)
277→	}
278→
279→	return action, nil
280→}
281→
282→// discardSession removes session state and cleans up the shadow branch.
283→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
284→	// Clear session state file
285→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
286→		return fmt.Errorf("failed to clear session state: %w", err)
287→	}
288→
289→	// Delete shadow branch if it exists and no other sessions need it
290→	if ss.HasShadowBranch {
291→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
292→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
293→		} else if shouldDelete {
294→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
295→				// Branch already gone is not an error — keeps discard idempotent
296→				if !errors.Is(err, strategy.ErrBranchNotFound) {
297→					return fmt.Errorf("failed to delete shadow branch: %w", err)
298→				}
299→			}
300→		}
301→	}
302→
303→	return nil
304→}
305→
306→// checkDisconnectedMetadata detects and optionally repairs disconnected
307→// local/remote metadata branches (the "empty-orphan bug").
308→func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
309→	repo, err := openRepository(cmd.Context())
310→	if err != nil {
311→		return fmt.Errorf("failed to open repository: %w", err)
312→	}
313→
314→	ctx := cmd.Context()
315→	disconnected, err := strategy.IsMetadataDisconnected(ctx, repo)
316→	if err != nil {
317→		return fmt.Errorf("could not check metadata branch state: %w", err)
318→	}
319→
320→	w := cmd.OutOrStdout()
321→
322→	if !disconnected {
323→		fmt.Fprintln(w, "Metadata branches: OK")
324→		return nil
325→	}
326→
327→	fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
328→	fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
329→	fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
330→	fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")
331→
332→	if !force {
333→		var confirmed bool
334→		form := NewAccessibleForm(
335→			huh.NewGroup(
336→				huh.NewConfirm().
337→					Title("Fix disconnected metadata branches?").
338→					Value(&confirmed),
339→			),
340→		)
341→		if formErr := form.Run(); formErr != nil {
342→			if errors.Is(formErr, huh.ErrUserAborted) {
343→				return nil
344→			}
345→			return fmt.Errorf("prompt failed: %w", formErr)
346→		}
347→		if !confirmed {
348→			fmt.Fprintln(w, "  -> Skipped")
349→			return nil
350→		}
351→	}
352→
353→	if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, cmd.ErrOrStderr()); fixErr != nil {
354→		return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
355→	}
356→
357→	fmt.Fprintln(w, "  -> Fixed: metadata branches reconciled")
358→	return nil
359→}
360→
361→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
362→// Returns true if no other sessions (besides excludeSessionID) need this branch.
363→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
364→	states, err := strategy.ListSessionStates(ctx)
365→	if err != nil {
366→		return false, fmt.Errorf("failed to list session states: %w", err)
367→	}
368→
369→	for _, state := range states {
370→		if state.SessionID == excludeSessionID {
371→			continue
372→		}
373→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
374→		if otherShadow == shadowBranch && state.StepCount > 0 {
375→			return false, nil
376→		}
377→	}
378→
379→	return true, nil
380→}
