	if got := childStepKey("check_content", seen); got != "check_content.1" {
		t.Errorf("second check_content = %q, want %q", got, "check_content.1")
	}
	if got := childStepKey("save_state", seen); got != "save_state.1" {
		t.Errorf("second save_state = %q, want %q", got, "save_state.1")
	}

	// Third occurrence gets .2
	if got := childStepKey("check_content", seen); got != "check_content.2" {
		t.Errorf("third check_content = %q, want %q", got, "check_content.2")
	}

	// Unique names are unaffected
	if got := childStepKey("unique_step", seen); got != "unique_step" {
		t.Errorf("unique_step = %q, want %q", got, "unique_step")
	}
