func TestEnd_GroupSpan_EmitsGrandchildren(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	ctx, root := Start(ctx, "post-commit")

	// Create a group span with iterations (grandchildren of root)
	groupCtx, group := Start(ctx, "process_sessions")
	_, iter0 := Start(groupCtx, "process_sessions")
	iter0.duration = 100 * time.Millisecond
	iter0.ended = true
	_, iter1 := Start(groupCtx, "process_sessions")
	iter1.duration = 200 * time.Millisecond
	iter1.ended = true
	group.duration = 300 * time.Millisecond
	group.ended = true

	root.End()

	// Verify group span has 2 children (the iterations)
	if len(group.children) != 2 {
		t.Fatalf("group should have 2 children, got %d", len(group.children))
	}
	if group.children[0] != iter0 {
		t.Error("group.children[0] should be iter0")
	}
	if group.children[1] != iter1 {
		t.Error("group.children[1] should be iter1")
	}
}

func TestEnd_GroupSpan_GrandchildrenAutoEnded(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	ctx, root := Start(ctx, "hook")
	groupCtx, group := Start(ctx, "loop")
	_, iter0 := Start(groupCtx, "loop")
	iter0.duration = 50 * time.Millisecond
	// iter0.ended intentionally NOT set — should be auto-ended
	group.duration = 50 * time.Millisecond
	group.ended = true

	root.End()

	if !iter0.ended {
		t.Error("grandchild should be auto-ended when root ends")
	}
}

func TestEnd_GroupSpan_WithErrors(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	ctx, root := Start(ctx, "hook")
	groupCtx, group := Start(ctx, "process_sessions")
	_, iter0 := Start(groupCtx, "process_sessions")
	iter0.duration = 100 * time.Millisecond
	iter0.ended = true
	_, iter1 := Start(groupCtx, "process_sessions")
	iter1.duration = 200 * time.Millisecond
	iter1.err = errors.New("session failed")
	iter1.ended = true
	group.duration = 300 * time.Millisecond
	group.ended = true

	root.End()

	// Verify error is on the correct grandchild
	if iter0.err != nil {
		t.Error("iter0 should have no error")
	}
	if iter1.err == nil {
		t.Error("iter1 should have error recorded")
	}
}

